"""Shared Selenium fixtures for provisional TELCO-6117 automation."""

import os

import pytest
from selenium import webdriver
from selenium.webdriver.chrome.options import Options


@pytest.fixture
def base_url() -> str:
    """Return the Contact us test URL supplied by the execution environment."""
    url = os.getenv("CONTACT_US_BASE_URL")
    if not url:
        pytest.fail(
            "CONTACT_US_BASE_URL is required. Set it to the Contact us test/staging URL."
        )
    return url.rstrip("/")


@pytest.fixture
def driver():
    """Provide a Chrome WebDriver; set SELENIUM_HEADLESS=true for CI."""
    options = Options()
    if os.getenv("SELENIUM_HEADLESS", "false").lower() == "true":
        options.add_argument("--headless=new")
    options.add_argument("--window-size=1440,1000")

    browser = webdriver.Chrome(options=options)
    browser.implicitly_wait(0)
    yield browser
    browser.quit()

"""Page object for TELCO-6117 Contact us flow.

All locators are provisional data-testid placeholders and must be mapped to the
implemented UI before the suite is used as a release gate.
"""

from selenium.webdriver.common.by import By
from selenium.webdriver.remote.webdriver import WebDriver
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.support.ui import WebDriverWait


class ContactUsPage:
    # TODO: Replace these placeholder selectors with application-owned selectors.
    FLOW_ROOT = (By.CSS_SELECTOR, '[data-testid="contact-us-flow"]')
    CONTACT_OPTION = (By.CSS_SELECTOR, '[data-testid="contact-option"]')
    CONTINUE_BUTTON = (By.CSS_SELECTOR, '[data-testid="contact-us-continue"]')
    AGENT_HANDOFF_BUTTON = (By.CSS_SELECTOR, '[data-testid="handoff-to-agent"]')
    AGENT_CONNECTED = (By.CSS_SELECTOR, '[data-testid="agent-connected"]')
    HANDOFF_UNAVAILABLE = (By.CSS_SELECTOR, '[data-testid="handoff-unavailable"]')
    FALLBACK_OPTION = (By.CSS_SELECTOR, '[data-testid="handoff-fallback"]')

    def __init__(self, driver: WebDriver, timeout_seconds: int = 15) -> None:
        self.driver = driver
        self.wait = WebDriverWait(driver, timeout_seconds)

    def open(self, base_url: str) -> None:
        self.driver.get(f"{base_url}/contact-us")
        self.wait.until(EC.visibility_of_element_located(self.FLOW_ROOT))

    def choose_first_contact_option(self) -> None:
        options = self.wait.until(EC.visibility_of_all_elements_located(self.CONTACT_OPTION))
        options[0].click()

    def continue_flow(self) -> None:
        self.wait.until(EC.element_to_be_clickable(self.CONTINUE_BUTTON)).click()

    def request_agent_handoff(self) -> None:
        self.wait.until(EC.element_to_be_clickable(self.AGENT_HANDOFF_BUTTON)).click()

    def agent_connection_is_displayed(self) -> bool:
        return self.wait.until(EC.visibility_of_element_located(self.AGENT_CONNECTED)).is_displayed()

    def handoff_unavailable_message_is_displayed(self) -> bool:
        return self.wait.until(EC.visibility_of_element_located(self.HANDOFF_UNAVAILABLE)).is_displayed()

    def fallback_option_is_displayed(self) -> bool:
        return self.wait.until(EC.visibility_of_element_located(self.FALLBACK_OPTION)).is_displayed()

"""Provisional Selenium coverage for TELCO-6117.

The agent-service state must be configured by the test environment before
running either hand-off scenario. The current ticket does not define the setup
mechanism, routing rules, or context-transfer contract.
"""

import pytest

from pages.contact_us_page import ContactUsPage


@pytest.mark.telco_6117
@pytest.mark.ac1
@pytest.mark.equivalence_partitioning
def test_customer_can_select_contact_option_and_continue(driver, base_url):
    """TC-TELCO-6117-001 | AC-1 | EP: implemented contact option."""
    contact_us = ContactUsPage(driver)

    contact_us.open(base_url)
    contact_us.choose_first_contact_option()
    contact_us.continue_flow()

    assert contact_us.driver.current_url.startswith(base_url)


@pytest.mark.telco_6117
@pytest.mark.ac5
@pytest.mark.state_transition
def test_customer_can_handoff_to_available_human_agent(driver, base_url):
    """TC-TELCO-6117-005 | AC-5 | State: flow -> agent connected.

    Precondition: configure the test environment so an agent is available.
    """
    contact_us = ContactUsPage(driver)

    contact_us.open(base_url)
    contact_us.request_agent_handoff()

    assert contact_us.agent_connection_is_displayed()


@pytest.mark.telco_6117
@pytest.mark.ac5
@pytest.mark.state_transition
def test_customer_is_given_fallback_when_agent_handoff_is_unavailable(driver, base_url):
    """TC-TELCO-6117-006 | AC-5 | State: flow -> hand-off unavailable -> fallback.

    Precondition: configure the test environment so hand-off is unavailable.
    """
    contact_us = ContactUsPage(driver)

    contact_us.open(base_url)
    contact_us.request_agent_handoff()

    assert contact_us.handoff_unavailable_message_is_displayed()
    assert contact_us.fallback_option_is_displayed()

